@props(['values','color'=>'#4b6eda','percent'=>false,'vertical'=>false,'links'=>[],'annotations'=>[]])
<?php $values=collect($values); $max=$percent?100:max(1,$values->max()??1); ?>
<div class="{{ $vertical?'hr-columns':'hr-bars' }}">@forelse($values as $name=>$value)<div @if(isset($links[$name])) class="dashboard-linked-bar" @endif title="{{ $name }}: {{ $value }}{{ $percent?'%':'' }}">@if(isset($links[$name]))<a class="dashboard-bar-link" href="{{ $links[$name] }}" aria-label="View {{ $name }}: {{ $value }}{{ $percent ? '%' : '' }}"></a>@endif @if($vertical)<strong>{{ number_format($value) }}</strong><div class="hr-column-track"><i style="height:{{ $value/$max*100 }}%;background:{{ $color }}"></i></div><span>{{ ucfirst(str_replace('_',' ',$name)) }}</span>@else<span>{{ ucfirst(str_replace('_',' ',$name)) }}</span><div class="hr-bar-track"><i style="width:{{ $value/$max*100 }}%;background:{{ $color }}"></i></div><strong>{{ number_format($value,$percent?1:0) }}{{ $percent?'%':'' }}@if(isset($annotations[$name]))<small class="chart-value-note">{{ $annotations[$name] }}</small>@endif</strong>@endif</div>@empty<p class="hr-empty">No data recorded for these filters.</p>@endforelse</div>
